callback_serializer.declarations:
extern "C" void WwiseDiag_RecordMonitor(AkUInt32 in_uErrorCode, AkUInt32 in_uErrorLevel,
                                         AkPlayingID in_playingID, AkGameObjectID in_gameObjID,
                                         const AkOSChar* in_pszError);
extern "C" AkUInt32 WwiseDiag_MonitorIsArmed();
extern "C" void WwiseDiag_SetManagedMonitorLevel(AkUInt32 in_uErrorLevel);
extern "C" int32_t WwiseDiag_ShouldSerializeMonitor(AkUInt32 in_uErrorLevel);

callback_serializer.monitor_scope:
// The native diagnostic remains installed through SoundEngine::Term and
// callback-manager Term. The owner disarms only after this method returns.
if (!WwiseDiag_MonitorIsArmed())

callback_serializer.record_monitor:
		// Count before the serializer-init guard; this records without queue allocation.
		WwiseDiag_RecordMonitor(static_cast<AkUInt32>(in_eErrorCode),
                                static_cast<AkUInt32>(in_eErrorLevel),
                                in_playingID, in_gameObjID, in_pszError);

callback_serializer.monitor_level:
WwiseDiag_SetManagedMonitorLevel(in_uErrorLevel);
// Keep the same callback installed while the native diagnostic is armed.
const AkUInt32 monitorErrorLevel = WwiseDiag_MonitorIsArmed()
	? static_cast<AkUInt32>(AK::Monitor::ErrorLevel_All) : in_uErrorLevel;
